    <div className="brand">
      <GloveMark size={size} />
      <div>
        <div className="brand-word" style={{ fontSize: wordSize }}>fightlytics</div>
        {sub && <div className="brand-sub">{sub}</div>}
      </div>
    </div>
  );
}

